-- Tracks and two job families (P5-T13; docs/plans/P5-production.md,
-- "Tracks" and "Two job families"): subtitles and chapters belong to the
-- asset, not to an output, so they survive a re-encode; a transcription is a
-- routed job of its own that runs beside the asset's encodes.

-- +goose Up
CREATE TABLE tracks (
    id          text PRIMARY KEY,
    project_id  text NOT NULL REFERENCES projects (id),
    asset_id    text NOT NULL REFERENCES assets (id),
    kind        text NOT NULL CHECK (kind IN ('subtitles', 'chapters')),
    -- generated by ClipMux; 'uploaded' is reserved for a later phase.
    source      text NOT NULL DEFAULT 'generated' CHECK (source IN ('generated', 'uploaded')),
    -- preparing → publishing (its VTT stored) → ready (its routes confirmed)
    -- → retired (a newer track of its kind became ready); preparing →
    -- errored; anything → deleted.
    status      text NOT NULL DEFAULT 'preparing'
        CHECK (status IN ('preparing', 'publishing', 'ready', 'retired', 'errored', 'deleted')),
    language    text,
    name        text,
    error_code  text,
    -- The content key secret version its VTT is sealed under.
    key_version integer,
    duration_ms bigint CHECK (duration_ms >= 0),
    -- A chapters track's chapters: [{start_ms, end_ms, title}].
    chapters    jsonb,
    -- The output whose audio (subtitles) or subtitles (chapters) it was made from.
    output_id   text,
    -- Bumped on every change the asset view shows (D020).
    version     bigint NOT NULL DEFAULT 1,
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now(),
    ready_at    timestamptz,
    retired_at  timestamptz,
    deleted_at  timestamptz,
    UNIQUE (id, asset_id),
    CHECK ((status = 'errored') = (error_code IS NOT NULL)),
    CHECK ((status = 'retired') = (retired_at IS NOT NULL))
);
-- At most one ready and one being made, per asset and kind: regenerating
-- makes a new track and retires the old one only once the new one is ready.
CREATE UNIQUE INDEX tracks_one_ready ON tracks (asset_id, kind) WHERE status = 'ready' AND source = 'generated';
CREATE UNIQUE INDEX tracks_one_preparing ON tracks (asset_id, kind)
    WHERE status IN ('preparing', 'publishing') AND source = 'generated';
CREATE INDEX tracks_asset ON tracks (asset_id);
CREATE INDEX tracks_retired_unpurged ON tracks (retired_at) WHERE status = 'retired';

-- The canonical transcript (internal/transcripts), apart from the track so
-- loading an asset stays light.
CREATE TABLE transcripts (
    track_id   text PRIMARY KEY REFERENCES tracks (id),
    project_id text NOT NULL REFERENCES projects (id),
    asset_id   text NOT NULL REFERENCES assets (id),
    body       jsonb NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX transcripts_asset ON transcripts (asset_id);

-- Connections to the speech API (D075) and the chapters LLM, one each per
-- project; the key is sealed (secrets.Columns) and optional, for keyless
-- servers on the owner's own network.
CREATE TABLE ai_connections (
    id              text PRIMARY KEY,
    project_id      text NOT NULL REFERENCES projects (id),
    purpose         text NOT NULL CHECK (purpose IN ('speech', 'chapters')),
    provider        text NOT NULL CHECK (provider IN ('openai_compatible', 'anthropic')),
    base_url        text,
    model           text NOT NULL,
    -- How chapters ask for JSON: a strict schema, or JSON mode for providers
    -- without one. Found by Connect.
    response_format text CHECK (response_format IN ('json_schema', 'json_object')),
    key_sealed      bytea,
    verified_at     timestamptz,
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now(),
    UNIQUE (project_id, purpose),
    CHECK (purpose <> 'speech' OR provider = 'openai_compatible'),
    CHECK (provider <> 'openai_compatible' OR base_url IS NOT NULL)
);

-- Jobs: transcribe (a routed worker job) and chapters (serve's own), each
-- for one track.
ALTER TABLE jobs ADD COLUMN track_id text REFERENCES tracks (id);
ALTER TABLE jobs DROP CONSTRAINT jobs_kind_check;
ALTER TABLE jobs ADD CONSTRAINT jobs_kind_check
    CHECK (kind IN ('import', 'transcode', 'reencode', 'move', 'delete', 'upload_source', 'transcribe', 'chapters'));
ALTER TABLE jobs ADD CONSTRAINT jobs_track_kinds CHECK ((track_id IS NOT NULL) = (kind IN ('transcribe', 'chapters')));
ALTER TABLE jobs DROP CONSTRAINT jobs_media_routed;
ALTER TABLE jobs ADD CONSTRAINT jobs_media_routed
    CHECK ((routed_to IS NOT NULL) = (kind IN ('transcode', 'reencode', 'upload_source', 'transcribe')));
-- A transcription reads an output, never a source, so it is never pinned.
ALTER TABLE jobs ADD CONSTRAINT jobs_transcribe_unpinned CHECK (kind <> 'transcribe' OR pinned_agent_id IS NULL);

-- One mutating job per asset becomes one per family: the outputs (import,
-- encodes, the source upload) and the tracks (transcription, chapters).
-- Move and delete are in both, so they stay exclusive with everything, and
-- two writers of the same thing never overlap.
DROP INDEX jobs_one_active_per_asset;
CREATE UNIQUE INDEX jobs_one_active_output ON jobs (asset_id) WHERE status IN ('queued', 'running')
    AND kind IN ('import', 'transcode', 'reencode', 'upload_source', 'move', 'delete');
CREATE UNIQUE INDEX jobs_one_active_track ON jobs (asset_id) WHERE status IN ('queued', 'running')
    AND kind IN ('transcribe', 'chapters', 'move', 'delete');

-- The output a transcription attempt reads: the asset's current output when
-- it was claimed, kept even if a re-encode commits meanwhile.
ALTER TABLE attempts ADD COLUMN input_output_id text;
ALTER TABLE attempts ADD CONSTRAINT attempts_input_output_fk
    FOREIGN KEY (input_output_id, asset_id) REFERENCES outputs (id, asset_id);

-- Whether the built-in worker said, at its last claim, that it can
-- transcribe; PC agents say so in agents.capabilities.
ALTER TABLE projects ADD COLUMN builtin_speech boolean NOT NULL DEFAULT false;

-- job_claimable_by gains the job's kind and whether the worker can
-- transcribe: a transcription needs speech, and its own disk rule (about
-- 1 GiB, plus 64 KiB a second for the audio and its WAV).
DROP FUNCTION job_claimable_by(text, text, text, boolean, boolean, bigint);
-- +goose StatementBegin
CREATE FUNCTION job_claimable_by(
    job_kind text, job_asset_id text, job_pinned_agent_id text,
    worker_agent_id text, worker_local_only boolean, worker_untrusted boolean, worker_free_disk bigint,
    worker_speech boolean
) RETURNS boolean LANGUAGE sql STABLE AS $$
    SELECT (coalesce(job_pinned_agent_id = worker_agent_id, false)
            OR (job_pinned_agent_id IS NULL AND NOT worker_local_only
                AND (NOT worker_untrusted OR EXISTS (
                    SELECT 1 FROM assets s JOIN apps p ON p.id = s.app_id
                    WHERE s.id = job_asset_id AND p.is_builtin))))
       AND (job_kind <> 'transcribe' OR worker_speech)
       AND (worker_free_disk IS NULL OR CASE WHEN job_kind = 'transcribe' THEN
                1073741824 + coalesce((SELECT ceil(s.duration_seconds * 65536)::bigint FROM assets s WHERE s.id = job_asset_id), 0)
            ELSE coalesce(
                (SELECT 3 * u.declared_size FROM uploads u WHERE u.asset_id = job_asset_id ORDER BY u.created_at DESC LIMIT 1),
                (SELECT 2 * g.size FROM assets s JOIN agent_sources g ON g.id = s.agent_source_id WHERE s.id = job_asset_id),
                0) END <= worker_free_disk)
$$;
-- +goose StatementEnd

-- +goose Down
-- The new kinds can't exist under the old model: they go, with their
-- attempts and dispatches, before the single index comes back.
DELETE FROM dispatches WHERE job_id IN (SELECT id FROM jobs WHERE kind IN ('transcribe', 'chapters'));
DELETE FROM attempts WHERE job_id IN (SELECT id FROM jobs WHERE kind IN ('transcribe', 'chapters'));
DELETE FROM jobs WHERE kind IN ('transcribe', 'chapters');
DROP FUNCTION job_claimable_by(text, text, text, text, boolean, boolean, bigint, boolean);
-- +goose StatementBegin
CREATE FUNCTION job_claimable_by(
    job_asset_id text, job_pinned_agent_id text,
    worker_agent_id text, worker_local_only boolean, worker_untrusted boolean, worker_free_disk bigint
) RETURNS boolean LANGUAGE sql STABLE AS $$
    SELECT (coalesce(job_pinned_agent_id = worker_agent_id, false)
            OR (job_pinned_agent_id IS NULL AND NOT worker_local_only
                AND (NOT worker_untrusted OR EXISTS (
                    SELECT 1 FROM assets s JOIN apps p ON p.id = s.app_id
                    WHERE s.id = job_asset_id AND p.is_builtin))))
       AND (worker_free_disk IS NULL OR coalesce(
            (SELECT 3 * u.declared_size FROM uploads u WHERE u.asset_id = job_asset_id ORDER BY u.created_at DESC LIMIT 1),
            (SELECT 2 * g.size FROM assets s JOIN agent_sources g ON g.id = s.agent_source_id WHERE s.id = job_asset_id),
            0) <= worker_free_disk)
$$;
-- +goose StatementEnd
ALTER TABLE projects DROP COLUMN builtin_speech;
ALTER TABLE attempts DROP CONSTRAINT attempts_input_output_fk, DROP COLUMN input_output_id;
-- Two families may each have an active job; the single index can't hold
-- both, so the older family's (outputs) job stays and a track job, if any,
-- was deleted above. Move and delete are in both and can't be doubled.
DROP INDEX jobs_one_active_track;
DROP INDEX jobs_one_active_output;
CREATE UNIQUE INDEX jobs_one_active_per_asset ON jobs (asset_id) WHERE status IN ('queued', 'running');
ALTER TABLE jobs DROP CONSTRAINT jobs_transcribe_unpinned;
ALTER TABLE jobs DROP CONSTRAINT jobs_media_routed;
ALTER TABLE jobs ADD CONSTRAINT jobs_media_routed
    CHECK ((routed_to IS NOT NULL) = (kind IN ('transcode', 'reencode', 'upload_source')));
ALTER TABLE jobs DROP CONSTRAINT jobs_track_kinds;
ALTER TABLE jobs DROP CONSTRAINT jobs_kind_check;
ALTER TABLE jobs ADD CONSTRAINT jobs_kind_check
    CHECK (kind IN ('import', 'transcode', 'reencode', 'move', 'delete', 'upload_source'));
ALTER TABLE jobs DROP COLUMN track_id;
DROP TABLE ai_connections;
DROP TABLE transcripts;
DROP TABLE tracks;
